import static org.mockito.Mockito.*;

public class DOMNodePointer_getNamespaceURI_TriageGen2Test {

    private Document createDocument(String xml) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setNamespaceAware(true);
        DocumentBuilder builder = factory.newDocumentBuilder();
        return builder.parse(new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)));
    }

    @Test
    public void testGetNamespaceURI_WithDocumentInput() throws Exception {
        String xml = "<root xmlns='http://test.uri/default'><child/></root>";
        Document doc = createDocument(xml);
        // The method logic: if node is Document, it uses getDocumentElement()
        String uri = DOMNodePointer.getNamespaceURI(doc);
        assertEquals("http://test.uri/default", uri);
    }

    @Test
    public void testGetNamespaceURI_WithElementDirectly() throws Exception {
        String xml = "<root xmlns='http://test.uri/direct'><child/></root>";
        Document doc = createDocument(xml);
        Element element = (Element) doc.getElementsByTagName("root").item(0);

        String uri = DOMNodePointer.getNamespaceURI(element);
        assertEquals("http://test.uri/direct", uri);
    }

    @Test
    public void testGetNamespaceURI_FallbackToDefaultNamespaceAttribute() throws Exception {
        // Case where element.getNamespaceURI() returns null, but xmlns attribute exists on self
        // We mock the element to simulate the internal behavior of a non-namespace-aware parser or specific DOM state
        Element mockElement = mock(Element.class);
        Attr mockAttr = mock(Attr.class);

        when(mockElement.getNamespaceURI()).thenReturn(null);
        when(mockElement.getAttributeNode("xmlns")).thenReturn(mockAttr);
        when(mockAttr.getValue()).thenReturn("http://test.uri/fallback");

        // Mock parent for the while loop
        when(mockElement.getParentNode()).thenReturn(null);

        String uri = DOMNodePointer.getNamespaceURI(mockElement);
        assertEquals("http://test.uri/fallback", uri);
    }

    @Test
    public void testGetNamespaceURI_FallbackToPrefixedNamespaceAttribute() throws Exception {
        // Case where prefix is found, so it looks for xmlns:prefix
        Element mockElement = mock(Element.class);
        Attr mockAttr = mock(Attr.class);

        when(mockElement.getNamespaceURI()).thenReturn(null);
        // We need to simulate getPrefix returning something. 
        // Since getPrefix is static, this test assumes getPrefix(node) logic in the class.
        // If getPrefix is implemented via node.getPrefix(), we mock that.
        when(mockElement.getPrefix()).thenReturn("test");

        when(mockElement.getAttributeNode("xmlns:test")).thenReturn(mockAttr);
        when(mockAttr.getValue()).thenReturn("http://test.uri/prefixed");
        when(mockElement.getParentNode()).thenReturn(null);

        String uri = DOMNodePointer.getNamespaceURI(mockElement);
        assertEquals("http://test.uri/prefixed", uri);
    }

    @Test
    public void testGetNamespaceURI_TraverseUpwardsToFindNamespace() throws Exception {
        // Case where current node has no URI and no attribute, but parent has xmlns
        Element parent = mock(Element.class);
        Element child = mock(Element.class);
        Attr parentAttr = mock(Attr.class);

        when(child.getNamespaceURI()).thenReturn(null);
        when(child.getPrefix()).thenReturn(null); // qname becomes "xmlns"
        when(child.getParentNode()).thenReturn(parent);
        when(child.getAttributeNode("xmlns")).thenReturn(null);

        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getNamespaceURI()).thenReturn(null);
        when(parent.getAttributeNode("xmlns")).thenReturn(parentAttr);
        when(parentAttr.getValue()).thenReturn("http://test.uri/parent");

        when(parent.getParentNode()).thenReturn(null);

        String uri = DOMNodePointer.getNamespaceURI(child);
        assertEquals("http://test.uri/parent", uri);
    }

    @Test
    public void testGetNamespaceURI_NoNamespaceFound() throws Exception {
        Element mockElement = mock(Element.class);
        when(mockElement.getNamespaceURI()).thenReturn(null);
        when(mockElement.getPrefix()).thenReturn(null);
        when(mockElement.getAttributeNode("xmlns")).thenReturn(null);
        when(mockElement.getParentNode()).thenReturn(null);

        String uri = DOMNodePointer.getNamespaceURI(mockElement);
        assertNull(uri);
    }

    @Test
    public void testGetNamespaceURI_TraverseUpToNonElementNode() throws Exception {
        // Ensure the while loop skips non-element nodes (like Text nodes)
        Element parent = mock(Element.class);
        Node textNode = mock(Node.class);
        Element child = mock(Element.class);
        Attr parentAttr = mock(Attr.class);

        when(child.getNamespaceURI()).thenReturn(null);
        when(child.getPrefix()).thenReturn(null);
        when(child.getParentNode()).thenReturn(textNode);
        when(child.getAttributeNode("xmlns")).thenReturn(null);

        when(textNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        when(textNode.getParentNode()).thenReturn(parent);

        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getNamespaceURI()).thenReturn(null);
        when(parent.getAttributeNode("xmlns")).thenReturn(parentAttr);
        when(parentAttr.getValue()).thenReturn("http://test.uri/found");
        when(parent.getParentNode()).thenReturn(null);

        String uri = DOMNodePointer.getNamespaceURI(child);
        assertEquals("http://test.uri/found", uri);
    }
}
